class Solution:
    def increasingTriplet(self, nums: list[int]) -> bool:
        lengths = [1] * len(nums)
        for i in range(len(nums)):
            for j in range(i):
                if nums[j] < nums[i]:
                    lengths[i] = max(lengths[i], lengths[j] + 1)
            if lengths[i] >= 3:
                return True
        return False
